cd /app && python3 -c "
from html.parser import HTMLParser

class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ('img','br','meta','input','hr','link'):
            self.tags.append(tag)
    def handle_endtag(self, tag):
        if tag not in ('img','br','meta','input','hr','link'):
            if self.tags and self.tags[-1] == tag:
                self.tags.pop()
            else:
                self.errors.append(f'Unexpected </{tag}>')

with open('/app/output/final_report.html','r') as f:
    content = f.read()

v = Validator()
v.feed(content)
print('Unclosed tags:', v.tags)
print('Errors:', v.errors)
print('Contains base64 images:', 'data:image/png;base64' in content)
print('Contains all sections:', all(s in content for s in ['tournament-overview','batting-analysis','bowling-analysis','team-comparison','extras-discipline','venue-insights']))
"
